--
-- Table structure for table `job_openings`
--

DROP TABLE IF EXISTS `job_openings`;
CREATE TABLE IF NOT EXISTS `job_openings` (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('open','closed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `posted_by` bigint UNSIGNED NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `job_openings_posted_by_foreign` (`posted_by`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `job_openings`
--

INSERT INTO `job_openings` (`id`, `title`, `description`, `status`, `posted_by`, `created_at`, `updated_at`) VALUES
(1, 'Barista', 'ChillVibe Cafe is looking for a friendly and energetic Barista to craft coffee and specialty drinks for our guests. You will greet customers, take orders, operate espresso machines, maintain cleanliness at the counter, and uphold our laid-back, welcoming brand experience. Prior barista experience is a plus but not required, as full training is provided. We are looking for someone reliable, punctual, and passionate about great customer service.', 'open', 2, '2026-07-24 02:00:00', '2026-07-24 02:00:00'),
(2, 'Store Manager', 'We are hiring a Store Manager to oversee daily operations at one of our ChillVibe branches. Responsibilities include supervising staff schedules, managing inventory, ensuring customer satisfaction, handling cash reconciliation, and enforcing company policies. The ideal candidate has at least 2 years of retail or hospitality management experience, strong leadership skills, and the ability to stay calm under pressure during peak hours.', 'open', 3, '2026-07-24 02:00:00', '2026-07-24 02:00:00'),
(3, 'Marketing Coordinator', 'ChillVibe is expanding its brand presence and needs a Marketing Coordinator to plan and execute promotional campaigns across social media, email, and in-store signage. You will collaborate with the design team, track campaign performance, and help grow our online community. A background in digital marketing, content creation, or communications is preferred.', 'open', 4, '2026-07-24 02:00:00', '2026-07-24 02:00:00'),
(4, 'Customer Service Representative', 'As a Customer Service Representative, you will be the first point of contact for customer inquiries, complaints, and feedback across phone, email, and chat channels. We are looking for someone with excellent communication skills, patience, and a genuine desire to resolve issues quickly while keeping the ChillVibe tone warm and approachable.', 'open', 5, '2026-07-24 02:00:00', '2026-07-24 02:00:00'),
(5, 'Social Media Specialist', 'We need a creative Social Media Specialist to manage ChillVibe\'s Instagram, TikTok, and Facebook accounts. Duties include content planning, shooting short videos, engaging with followers, and analyzing engagement metrics. Experience with Canva, CapCut, or similar tools and a strong eye for aesthetics is highly valued.', 'open', 6, '2026-07-24 02:00:00', '2026-07-24 02:00:00'),
(6, 'Event Coordinator', 'The Event Coordinator will plan and execute in-store events, brand activations, and community pop-ups that reflect the relaxed, feel-good ChillVibe lifestyle. This role requires strong organizational skills, vendor coordination experience, and the ability to manage multiple events at once, often under tight timelines.', 'open', 7, '2026-07-24 02:00:00', '2026-07-24 02:00:00'),
(7, 'Delivery Rider', 'ChillVibe is looking for a Delivery Rider to ensure our products reach customers quickly and safely. You must have a valid motorcycle license, know the local area well, and be comfortable working flexible shifts, including weekends. Punctuality and safe driving habits are essential for this role.', 'closed', 8, '2026-07-24 02:00:00', '2026-07-24 02:00:00'),
(8, 'Cleaning & Facilities Staff', 'We are hiring Cleaning & Facilities Staff to keep our stores spotless, safe, and welcoming for both customers and employees. Tasks include daily cleaning routines, restocking supplies, basic maintenance checks, and reporting facility issues to management. No prior experience required; training will be provided.', 'closed', 9, '2026-07-24 02:00:00', '2026-07-24 02:00:00'),
(9, 'IT Support Technician', 'ChillVibe\'s growing network of stores needs an IT Support Technician to maintain point-of-sale systems, store Wi-Fi, and employee devices. You will troubleshoot hardware and software issues, coordinate with our vendors, and provide remote and on-site support. Basic networking knowledge and a problem-solving mindset are required.', 'open', 10, '2026-07-24 02:00:00', '2026-07-24 02:00:00'),
(10, 'Accounting Assistant', 'We are looking for a detail-oriented Accounting Assistant to support our finance team with data entry, invoice processing, payroll reconciliation, and expense tracking. Familiarity with spreadsheets and basic bookkeeping principles is required; experience with accounting software is a plus.', 'closed', 11, '2026-07-24 02:00:00', '2026-07-24 02:00:00');

